declare const tools: { mcp__neuronet__neuronet_code_search(args: {
  // search | list_repositories | get_file
  action: "search" | "list_repositories" | "get_file";
  endLine?: number;
  limit?: number;
  // search only. content (default): match chunk CONTENTS, case-insensitive. path: match file PATHS/names (locate a file); with a repo this is a case-sensitive substring match (the query is also tried lowercased) scoped to one ref.
  mode?: "content" | "path";
  // path substring (search); file path (required for get_file)
  path?: string;
  provider?: "github" | "gitlab";
  // search terms (search); repo-name filter (list_repositories)
  query?: string;
  // Optional branch/ref filter (e.g. 'main'). search (path mode with a repo): if omitted (or blank) the repo's live default ref is used (main, else master, else newest synced; resolved per provider when 'provider' is not given) and echoed back as 'refDefaultedTo' (a string, or a {provider: ref} map when providers default differently) — pass a ref explicitly to search another branch. get_file: pins the ref; if omitted the most recently synced copy of the file is used.
  ref?: string;
  // exact repo (search filter; required for get_file)
  repo?: string;
  startLine?: number;
}): Promise<CallToolResult>; };
```"}]

