declare const tools: { mcp__neuronet__neuronet_submit(args: {
  // The message to send to the agent
  message: string;
  // Optional model for THIS turn, as a provider/model id from the deployment's catalogue (GET /v1/models), e.g. "anthropic/claude-sonnet-5[1m]" or "openrouter/deepseek/deepseek-v4.1-flash". Omit to use your default. An unknown or disallowed id is refused, never substituted. Do NOT write "/model …" in the message — it is refused on this path.
  model?: string;
  // Optional thinking effort for THIS turn only (not saved). Omit to use your default. Do NOT write "/think …" in the message — it is refused on this path.
  thinkLevel?: "off" | "minimal" | "low" | "medium" | "high" | "xhigh" | "max";
}): Promise<CallToolResult>; };
