      "content": "import { metrics, SpanStatusCode, trace } from "@opentelemetry/api";

export type WorkOperation =
  "claim.nft" | "claim.erc20" | "transaction.submit" | "transaction.receipt";

// One event per invocation; these are attempts, not deduplicated mint totals.
export async function observeWork<T>(
  operation: WorkOperation,
  fn: () => Promise<T>,
): Promise<T> {
  return trace
    .getTracer("web3-minting-service")
    .startActiveSpan(operation, async (span) => {
      const started = performance.now();
      let outcome = "success";
      try {
        return await fn();
      } catch (error) {
        outcome = "error";
        span.setStatus({ code: SpanStatusCode.ERROR });
        throw error;
      } finally {
        const meter = metrics.getMeter("web3-minting-service");
        const attrs = { operation, outcome };
        meter.createCounter("web3minting.work.attempts").add(1, attrs);
        meter
          .createHistogram("web3minting.work.duration", { unit: "s" })
          .record((performance.now() - started) / 1000, attrs);
        span.setAttributes(attrs);
        span.end();
      }
    });
}

export function transactionPhase(phase: "accepted" | "receipt_observed"): void {
  metrics
    .getMeter("web3-minting-service")
    .createCounter("web3minting.transaction.phases")
    .add(1, { phase });
