const links: DeepLinkRegistration[] = [
    { id: 'tabs.rewards', kind: 'tab', routeName: 'Rewards', path: 'rewards' },
    {
        id: 'campaign-details',
        kind: 'stack',
        routeName: 'CampaignDetails',
        path: 'campaign-details/:campaign_id?',
    },
    { id: 'shop-item', kind: 'stack', routeName: 'ShopItem', path: 'shop/item' },
