        id: 'quest',
        kind: 'stack',
        routeName: 'CampaignDetails',
        path: 'quest/:campaign_id',
        routePath: 'campaign-details/:campaign_id?',
    },
];

const linking = buildLinking(createDeepLinkRegistry(links));
const getPathFromState = linking.getPathFromState!;
const getStateFromPath = linking.getStateFromPath!;

describe('buildLinking getPathFromState', () => {
    it('drops object params instead of writing [object Object] to the URL', () => {
        const path = getPathFromState(
            { routes: [{ name: 'ShopItem', params: { item: { utid: 'u-1' }, ref: 'home' } }] },
            linking.config,
        );

        expect(path).toBe('/shop/item?ref=home');
    });"
